package io.github.jesterportfolio.hearth.survival.rpg;

import java.nio.file.*;import java.nio.channels.FileChannel;import java.util.*;import java.util.concurrent.*;
import org.bukkit.*;import org.bukkit.plugin.java.JavaPlugin;
import io.github.jesterportfolio.hearth.economy.RpgStore;
import io.github.jesterportfolio.hearth.survival.*;
import io.github.jesterportfolio.hearth.administration.RuntimeLease;

/** 기존 3월드 registry/PG hash를 바꾸지 않고 두 추가 월드를 별도 native binding으로 봉인한다. */
public final class ExtraWorlds {
    private final JavaPlugin plugin;private final SurvivalWorlds worlds;private final RpgStore store;private final Properties config;
    private final UUID group,realm;private final Executor owner;private final Path registry,pending;private final Properties saved=new Properties();
    private final List<SurvivalWorld> roles=List.of(SurvivalWorld.NOVICE,SurvivalWorld.END);private final List<RpgStore.Extra> prepared=new ArrayList<>();
    private RuntimeLease.Lease lease;
    public ExtraWorlds(JavaPlugin plugin,SurvivalWorlds worlds,RpgStore store,Properties config,UUID group,UUID realm,Executor owner){this.plugin=plugin;this.worlds=worlds;this.store=store;this.config=config;this.group=group;this.realm=realm;this.owner=owner;registry=plugin.getDataFolder().toPath().toAbsolutePath().resolve("survival-extra-worlds.properties");pending=registry.resolveSibling("survival-extra-worlds.pending");}
    public CompletionStage<Void> open(RpgStore.Snapshot state){try{
        if(Files.exists(pending,LinkOption.NOFOLLOW_LINKS))throw new IllegalStateException("EXTRA_PREPARATION_HOLD");boolean existing=Files.exists(registry,LinkOption.NOFOLLOW_LINKS);
        if(existing){if(state.extras().size()!=2)throw new IllegalStateException("EXTRA_ROWS");if(!registry.equals(registry.toRealPath())||Files.size(registry)>16384)throw new IllegalStateException("EXTRA_REGISTRY_PATH");try(var r=Files.newBufferedReader(registry)){saved.load(r);}if(!"1".equals(saved.getProperty("format"))||!group.toString().equals(saved.getProperty("group"))||!realm.toString().equals(saved.getProperty("realm")))throw new IllegalStateException("EXTRA_REGISTRY_OWNER");}
        else{if(!RpgPolicy.bool(config,"allow-create-extras")||!state.extras().isEmpty())throw new IllegalStateException("EXTRA_PREPARATION_REQUIRED");lease=RuntimeLease.acquire(pending,"Hearth extra world preparation v1\n"+group+"\n"+realm+"\n").orElseThrow();saved.setProperty("format","1");saved.setProperty("group",group.toString());saved.setProperty("realm",realm.toString());}
        return prepare(0,existing,state).thenComposeAsync(v->{if(existing)return CompletableFuture.completedFuture(null);try{try(var writer=Files.newBufferedWriter(registry,StandardOpenOption.CREATE_NEW)){saved.store(writer,"Hearth extra world ownership v1");}try(var channel=FileChannel.open(registry,StandardOpenOption.WRITE)){channel.force(true);}}catch(Exception e){return CompletableFuture.failedFuture(e);}CompletionStage<Void> chain=CompletableFuture.completedFuture(null);for(var extra:prepared)chain=chain.thenCompose(ignored->store.bindExtra(extra));return chain.thenRunAsync(()->{try{lease.clean();}catch(Exception e){throw new CompletionException(e);}},owner);},owner);
    }catch(Exception error){return CompletableFuture.failedFuture(error);}}
    private CompletionStage<Void> prepare(int index,boolean existing,RpgStore.Snapshot state){if(index==roles.size())return CompletableFuture.completedFuture(null);var role=roles.get(index);String id=role.id(),key=config.getProperty("extra."+id+".key","hearth_survival:"+(role==SurvivalWorld.END?"resource_end":"novice"));
        try{if(!key.matches("hearth_survival:[a-z0-9_]+"))throw new IllegalArgumentException("EXTRA_KEY");var ns=Objects.requireNonNull(NamespacedKey.fromString(key));Path level=Bukkit.getServer().getLevelDirectory().toRealPath(),path=level.resolve("dimensions").resolve(ns.getNamespace()).resolve(ns.getKey());for(Path parent=path;parent!=null&&!parent.equals(level);parent=parent.getParent())if(Files.isSymbolicLink(parent))throw new IllegalStateException("EXTRA_PATH");
            RpgStore.Extra recorded=null;if(existing){recorded=new RpgStore.Extra(id,saved.getProperty(id+".key"),UUID.fromString(saved.getProperty(id+".uuid")),Long.parseLong(saved.getProperty(id+".seed")));if(config.containsKey("extra."+id+".seed")&&Long.parseLong(config.getProperty("extra."+id+".seed"))!=recorded.seed())throw new IllegalStateException("EXTRA_SEED_CHANGED");if(!key.equals(recorded.key())||!SurvivalWorlds.metadataUuid(path.resolve("data/paper/metadata.dat")).equals(recorded.world())||!state.extras().contains(recorded))throw new IllegalStateException("EXTRA_IDENTITY_MISMATCH");}else if(Files.exists(path,LinkOption.NOFOLLOW_LINKS)||Bukkit.getWorld(ns)!=null)throw new IllegalStateException("EXTRA_UNKNOWN_WORLD");
            var env=role==SurvivalWorld.END?World.Environment.THE_END:World.Environment.NORMAL;var creator=WorldCreator.ofKey(ns).environment(env);String terrain=config.getProperty("extra."+id+".terrain","NORMAL");if(!Set.of("NORMAL","FLAT").contains(terrain)||role==SurvivalWorld.END&&!terrain.equals("NORMAL"))throw new IllegalArgumentException("EXTRA_TERRAIN");if(existing&&!terrain.equals(saved.getProperty(id+".terrain")))throw new IllegalStateException("EXTRA_TERRAIN_CHANGED");creator.type(WorldType.valueOf(terrain));if(config.containsKey("extra."+id+".seed"))creator.seed(Long.parseLong(config.getProperty("extra."+id+".seed")));
            var world=Objects.requireNonNull(Bukkit.createWorld(creator));if(world.getEnvironment()!=env||recorded!=null&&(!recorded.world().equals(world.getUID())||recorded.seed()!=world.getSeed()))throw new IllegalStateException("EXTRA_WORLD_CHANGED");
            var hint=existing?new Location(world,Double.parseDouble(saved.getProperty(id+".x")),Double.parseDouble(saved.getProperty(id+".y")),Double.parseDouble(saved.getProperty(id+".z"))):world.getSpawnLocation();
            if(existing&&!world.isChunkGenerated(hint.getBlockX()>>4,hint.getBlockZ()>>4))throw new IllegalStateException("EXTRA_CHUNK_MISSING");
            return world.getChunkAtAsync(hint.getBlockX()>>4,hint.getBlockZ()>>4,!existing).thenComposeAsync(chunk->{if(chunk==null)throw new IllegalStateException("EXTRA_CHUNK");Location at=existing?hint:SurvivalWorlds.findSafe(world,hint);if(!SurvivalWorlds.safe(at))throw new IllegalStateException("EXTRA_ENTRY_UNSAFE");worlds.addExtra(role,world,at);var row=new RpgStore.Extra(id,key,world.getUID(),world.getSeed());prepared.add(row);if(!existing){world.save(true);saved.setProperty(id+".terrain",terrain);saved.setProperty(id+".key",key);saved.setProperty(id+".uuid",world.getUID().toString());saved.setProperty(id+".seed",""+world.getSeed());saved.setProperty(id+".x",""+at.getX());saved.setProperty(id+".y",""+at.getY());saved.setProperty(id+".z",""+at.getZ());}return prepare(index+1,existing,state);},owner);
        }catch(Exception error){return CompletableFuture.failedFuture(error);}
    }
    public String inspect(){return "extra_registry="+Files.isRegularFile(registry)+" pending="+Files.exists(pending)+" prepared="+prepared;}
}
